THOUGHT: I’ll create a single dependency-free Python service with shared file-backed state, three HTTP listeners selected by port, core REST resources, a browser SPA containing the required semantic hooks, and lightweight WebSocket/IRC handling. This establishes a runnable baseline quickly for iterative testing.

```mswea_bash_command
cat > /app/server.py <<'PY'
import os,json,re,uuid,hashlib,base64,threading,time,datetime,urllib.parse,socket,struct
from http.server import ThreadingHTTPServer,BaseHTTPRequestHandler
from email.parser import BytesParser
from email.policy import default
DATA='/app/data/state.json'; LOCK=threading.RLock(); CLIENTS=[]; IRC_CLIENTS=[]
def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def load():
    with LOCK:
        try:
            with open(DATA) as f:return json.load(f)
        except:return {'users':{},'tokens':{},'workspaces':{},'channels':{},'messages':{},'events':{},'files':{},'groups':{},'invites':{}}
def save(s):
    os.makedirs('/app/data',exist_ok=True)
    t=DATA+'.tmp'
    with open(t,'w') as f: json.dump(s,f)
    os.replace(t,DATA)
def uid(): return uuid.uuid4().hex
def userobj(u): return {k:u.get(k,'') for k in ['id','username','display_name','timezone','avatar_url','status_text','status_emoji']}
def channelobj(c): return {k:c.get(k) for k in ['id','workspace_id','name','is_private','is_dm','topic','is_archived']}
def msgobj(m,s):
    a=s['users'].get(m['author_id'],{})
    reactions=[]
    for e,ids in m.get('reactions',{}).items(): reactions.append({'emoji':e,'count':len(ids),'user_ids':ids})
    return {'id':m['id'],'channel_id':m['channel_id'],'author_id':m['author_id'],'author':userobj(a),'body':m['body'],'parent_id':m.get('parent_id'),'reply_count':sum(1 for x in s['messages'].values() if x.get('parent_id')==m['id'] and not x.get('deleted')),'created_at':m['created_at'],'edited_at':m.get('edited_at'),'files':m.get('files',[]),'reactions':reactions,'mentions':m.get('mentions',[])}
def jsonout(h,code,obj):
    b=json.dumps(obj).encode(); h.send_response(code); h.send_header('Content-Type','application/json'); h.send_header('Content-Length',str(len(b))); h.end_headers(); h.wfile.write(b)
HTML='''<!doctype html><html><head><meta charset=utf-8><title>Huddle</title><style>
*{box-sizing:border-box}body{margin:0;font-family:Arial;color:#222}button{border:0;border-radius:4px;padding:9px 14px;color:#fff;cursor:pointer}.primary{background:#007a5a}.danger{background:#e01e5a}.secondary{background:#1264a3}#app{display:flex;height:100vh}.side{width:260px;background:#3f0e40;color:white;padding:18px}.main{flex:1;padding:25px;position:relative}.thread{width:330px;border-left:1px solid #ddd;padding:20px}.entry{padding:10px;border-radius:5px;cursor:pointer}.entry:hover{background:#eee}.msg{padding:12px;border-bottom:1px solid #eee}.muted{color:#777}.modal{position:fixed;inset:0;background:#0008;display:flex;align-items:center;justify-content:center}.card{background:white;padding:25px;border-radius:8px;min-width:330px}input,select{padding:10px;margin:5px;width:calc(100% - 10px)}[hidden]{display:none!important}</style></head><body>
