async function select(c){channel=c;$('#channel-title').textContent='#'+c.name;$('#channel-topic').textContent=c.topic||'';let j=await api('/channels/'+c.id+'/messages');$('#message-list').innerHTML=j.messages.reverse().map(render).join('');$('#empty-state').hidden=!!j.messages.length;document.querySelectorAll('.open-thread').forEach(x=>x.onclick=()=>thread(x.dataset.id))}
